pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        try c.withdrawBalance() {} catch { return; }
        uint balBefore = address(c).balance;
        uint256 recBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { recBefore = __r; } catch { return; }
        try c.withdrawBalance() {} catch { return; }
        uint balAfter = address(c).balance;
        uint256 recAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { recAfter = __r; } catch { return; }
        assertTrue(recBefore == 0 && recAfter == 0 && balBefore == balAfter);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
